async function fixture(throughSchema?:number){const f=await workFixture({throughSchema});try{
 let taxRole:string|undefined;if(throughSchema===undefined||throughSchema>=169){taxRole=(await f.made('roles',{name:'Explicit synthetic tax settings administrators',permissions:[{capability:'payroll-tax.view',effect:'allow'},{capability:'payroll-tax.edit',effect:'allow'}]})).id;for(const p of [f.actors.staff.person,f.actors.manager.person,f.bot])await f.pg.query('INSERT INTO public.role_assignments(academy_id,id,person_id,role_id,all_hubs) VALUES($1,$2,$3,$4,true)',[f.a,randomUUID(),p,taxRole]);const reviewRole=await f.made('roles',{name:'Explicit synthetic school-wide approval reviewer',permissions:[{capability:'approvals.view',effect:'allow'},{capability:'approvals.review',effect:'allow'}]});await f.pg.query('INSERT INTO public.role_assignments(academy_id,id,person_id,role_id,all_hubs) VALUES($1,$2,$3,$4,true)',[f.a,randomUUID(),f.actors.manager.person,reviewRole.id]);}
 const definition={active:true,countryCode:'CA',provinceOfEmployment:'ON',federalTd1:{status:'recorded',claimAmount:'10000.00',sourceReference:'PRIVATE synthetic federal form reference'},provincialDeclaration:{status:'recorded',claimAmount:'8000.00',sourceReference:'PRIVATE synthetic provincial form reference'},additionalIncomeTaxPerPay:'10.00',incomeTaxExemption:'none',incomeTaxExemptionReference:null,pension:{plan:'CPP',status:'subject',pensionableMonths:12,sourceReference:'PRIVATE synthetic pensionability review'},ei:{status:'subject',employerPlan:'standard_1_4',multiplier:'1.4',sourceReference:'PRIVATE synthetic insurability review'},review:'PRIVATE synthetic declared tax facts,not government verification'},input={personId:f.actors.staff.person,employer:{id:f.employer.id,version:1},taxYear:2026,effectiveOn:'2026-01-01',definition,reason:'PRIVATE tax profile review'};
 const createTax=(patch:Record<string,unknown>={},as='master',key?:string)=>f.request('payroll/tax-profiles',{...input,...patch},as,{key});return {...f,taxRole,definition,taxInput:input,createTax};
 }catch(e){await f.pg.close();throw e;}}
type F=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:F)=>Promise<void>,nativeOnly=false){test(name,{skip:nativeOnly&&!process.env.TEST_DATABASE_URL},async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.close();}});}
const employerDefinition=()=>({active:true,address:{lines:['123 Synthetic Street'],city:'Toronto',region:'Ontario',postalCode:'A1A 1A1',countryCode:'CA'},review:'PRIVATE_EMPLOYER reviewed reporting address,not CRA verification'});
async function employerAccess(f:F){const r=await f.made('roles',{name:'Synthetic private employer administrators',permissions:['payroll-employers.view','payroll-employers.edit','payees.view','approvals.view','approvals.review'].map(capability=>({capability,effect:'allow'}))});for(const who of [f.actors.staff.person,f.actors.manager.person,f.bot])await f.pg.query('INSERT INTO public.role_assignments(academy_id,id,person_id,role_id,all_hubs) VALUES($1,$2,$3,$4,true)',[f.a,randomUUID(),who,r.id]);return r.id;}
const employerInput=(f:F,patch:Record<string,unknown>={})=>({employer:{id:f.employer.id,version:1},code:'RP-MAIN',accountNumber:'123456789RP0001',effectiveOn:'2026-01-01',definition:employerDefinition(),reason:'PRIVATE_EMPLOYER source review',...patch});
