 v=(await f.request(access)).body.data.version;assert.equal((await f.request(access,{expectedVersion:v,assignments:[{roleId:role,allHubs:true}]})).response.status,200);assert.equal((await f.request(path,undefined,'manager')).response.status,200);await f.pg.query('UPDATE auth_private.credentials SET all_hubs=false WHERE id=$1',[f.botAuth.credentialId]);await f.pg.query('INSERT INTO auth_private.credential_hubs VALUES($1,$2,$3)',[f.botAuth.credentialId,f.a,f.hub]);assert.equal((await f.request(path,undefined,'bot')).response.status,403);assert.equal((await f.request('payroll/employer-accounts?limit=1',undefined,'bot')).response.status,403);
