check('payroll employer native exact-review guard rejects a pending approval with a forged reporting address',async f=>{
 await employerAccess(f);const input=employerInput(f),r=await f.request('payroll/employer-accounts',input,'staff');assert.equal(r.response.status,202);const p=(await f.pg.query<any>('SELECT * FROM public.approval_requests WHERE id=$1',[r.body.approval.id])).rows[0];await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_runtime');await f.pg.query('INSERT INTO public.payroll_employer_accounts(academy_id,id,employer_id,code,account_number) VALUES($1,$2,$3,$4,$5)',[f.a,p.target_id,f.employer.id,input.code,input.accountNumber]);await assert.rejects(f.pg.query("INSERT INTO public.payroll_employer_revisions(academy_id,account_id,version,effective_on,employer_version,definition,source_snapshot,changed_by,approval_id,reason) VALUES($1,$2,1,'2026-01-01',1,$3::jsonb,$4::jsonb,$5,$6,$7)",[f.a,p.target_id,JSON.stringify({...input.definition,address:{...input.definition.address,city:'Forged city'}}),JSON.stringify(p.review_context),f.actors.master.person,p.id,input.reason]),/PAYROLL_EMPLOYER_EXACT_REVIEW_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.pg.query('SELECT * FROM public.payroll_employer_accounts')).rows.length,0);assert.equal((await f.approve(p.id)).response.status,200);
});
test('payroll employer actual186to187 upgrade preserves existing financial tax policy and private history without guessing employer accounts',async()=>{
 const f=await fixture(186);try{const r=await f.createTax();assert.equal(r.response.status,201);const tables=['people','roles','role_permissions','role_assignments','financial_payees','financial_payee_revisions','payroll_tax_profiles','payroll_tax_profile_revisions','finance_journals','approval_requests','audit_events'],snapshot=async()=>{const rows=[];for(const t of tables)rows.push((await f.pg.query('SELECT * FROM public.'+t+' ORDER BY 1,2')).rows);return rows;},before=await snapshot();await f.pg.exec(await readFile(new URL('../db/migrations/187_payroll_employer_accounts.sql',import.meta.url),'utf8'));assert.equal((await f.pg.query('SELECT public.schema_revision() v')).rows[0].v,187);assert.deepEqual(await snapshot(),before);for(const t of ['payroll_employer_accounts','payroll_employer_revisions'])assert.equal((await f.pg.query('SELECT * FROM public.'+t)).rows.length,0);await upgradeToCurrent(f.pg);const created=await f.request('payroll/employer-accounts',employerInput(f));assert.equal(created.response.status,201,JSON.stringify({body:created.body,failures:f.metrics.queryFailures}));assert.equal(created.body.data.legalEmployerName,'Synthetic Academy Inc.');}finally{await f.pg.close();}
});
