check('native payroll reporting default and account correction serialize the selected source or refuse an obsolete default',async f=>{
 await employerAccess(f);const r=await f.request('payroll/employer-accounts',employerInput(f));assert.equal(r.response.status,201);const ref={id:r.body.data.id,version:1},definition={...f.definition,reportingAccount:ref},[created,changed]=await Promise.all([f.createTax({definition}),f.request('payroll/employer-accounts/'+ref.id+'/change',{expectedVersion:1,employer:f.taxInput.employer,effectiveOn:'2026-01-01',definition:{...employerDefinition(),address:{...employerDefinition().address,city:'Concurrent corrected city'}},reason:'Reviewed simultaneous account correction'})]);assert.equal(changed.response.status,200,JSON.stringify(changed.body));assert.ok([201,409].includes(created.response.status),JSON.stringify({body:created.body,failures:f.metrics.queryFailures}));if(created.response.status===201){const row=(await f.pg.query<any>('SELECT definition,source_snapshot FROM public.payroll_tax_profile_revisions WHERE profile_id=$1',[created.body.data.id])).rows[0];assert.deepEqual(row.definition.reportingAccount,ref);assert.equal(row.source_snapshot.reportingAccount.version,1);const hash=(await f.pg.query<{hash:string}>("SELECT encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex') hash FROM public.payroll_employer_revisions r WHERE account_id=$1 AND version=1",[ref.id])).rows[0].hash;assert.equal(row.source_snapshot.reportingAccount.revisionSha256,hash);}else{assert.equal(created.body.error.code,'PAYROLL_REPORTING_ACCOUNT_CHANGED');assert.equal((await f.pg.query('SELECT * FROM public.payroll_tax_profiles')).rows.length,0);}
},true);
