check('tax settings strict input and native shape checks refuse SINs unsupported forms bad money and invented automatic authority',async f=>{
 for(const patch of [{sin:'123456789'},{taxYear:1899},{effectiveOn:'2027-01-01'},{definition:{...f.definition,sin:'123456789'}},{definition:{...f.definition,additionalIncomeTaxPerPay:'0.001'}},{definition:{...f.definition,federalTd1:{...f.definition.federalTd1,status:'not_provided'}}},{definition:{...f.definition,pension:{...f.definition.pension,pensionableMonths:13}}},{definition:{...f.definition,ei:{...f.definition.ei,multiplier:'1.24'}}}])assert.equal((await f.createTax(patch)).response.status,400,JSON.stringify(patch));
 const parsed=(await f.createTax()).body.data;assert.equal(parsed.definition.federalTd1.claimAmount,'10000.00');for(const bad of [{...f.definition,sin:'123456789'},{...f.definition,provinceOfEmployment:'XX'},{...f.definition,pension:{...f.definition.pension,pensionableMonths:'12'}},{...f.definition,ei:{...f.definition.ei,multiplier:'1.00001'}},{...f.definition,additionalIncomeTaxPerPay:'0.001'}])assert.equal((await f.pg.query<{ok:boolean}>('SELECT public.payroll_tax_definition_valid($1::jsonb) ok',[JSON.stringify(bad)])).rows[0].ok,false);
 await assert.rejects(f.pg.query("UPDATE public.payroll_tax_profile_revisions SET reason='rewritten'"),/PAYROLL_TAX_HISTORY_IMMUTABLE/);await assert.rejects(f.pg.query('DELETE FROM public.payroll_tax_profile_revisions'),/PAYROLL_TAX_HISTORY_IMMUTABLE/);await assert.rejects(f.pg.query('UPDATE public.payroll_tax_profiles SET tax_year=2027,version=version+1'),/PAYROLL_TAX_IDENTITY_IMMUTABLE/);
});
check('tax settings record Quebec QPP and declared reduced EI without claiming verified eligibility or calculating contributions',async f=>{
 const definition={...f.definition,provinceOfEmployment:'QC',pension:{...f.definition.pension,plan:'QPP'},ei:{...f.definition.ei,employerPlan:'declared_reduced',multiplier:'1.24'}};const r=await f.createTax({definition});assert.equal(r.response.status,201,JSON.stringify(r.body));assert.equal(r.body.data.definition.pension.plan,'QPP');assert.equal(r.body.data.governmentFormsVerified,false);assert.equal(r.body.data.statutoryRulesCalculated,false);assert.equal(r.body.data.payrollReady,false);for(const d of [{...definition,pension:{...definition.pension,plan:'CPP'}},{...f.definition,pension:{...f.definition.pension,plan:'QPP'}},{...f.definition,pension:{...f.definition.pension,plan:'needs_review'}}]){assert.equal((await f.createTax({taxYear:2027,effectiveOn:'2027-01-01',definition:d})).response.status,400);assert.equal((await f.pg.query<{ok:boolean}>('SELECT public.payroll_tax_definition_valid($1::jsonb) ok',[JSON.stringify(d)])).rows[0].ok,false);}
});
check('tax settings audit failure rolls back approval profile history and exact retry receipt together',async f=>{
 const key=randomUUID();await f.pg.exec("CREATE FUNCTION public.fail_tax_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action='work.tax-profile.create' THEN RAISE EXCEPTION 'synthetic tax audit failure';END IF;RETURN NEW;END$$;CREATE TRIGGER fail_tax_audit BEFORE INSERT ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.fail_tax_audit()");assert.equal((await f.createTax({},'master',key)).response.status,503);assert.equal((await f.pg.query('SELECT * FROM public.payroll_tax_profiles')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.payroll_tax_profile_revisions')).rows.length,0);await f.pg.exec('DROP TRIGGER fail_tax_audit ON public.audit_events');assert.equal((await f.createTax({},'master',key)).response.status,201);
});
check('tax settings tiny native concurrent creators and amendments keep one winner and exact history',async f=>{
 const created=await Promise.all(['A','B'].map(reason=>f.createTax({reason})));assert.deepEqual(created.map(r=>r.response.status).sort(),[201,409],JSON.stringify(created.map(r=>r.body)));const id=created.find(r=>r.response.status===201)!.body.data.id,changed=await Promise.all(['1.00','2.00'].map(additionalIncomeTaxPerPay=>f.request('payroll/tax-profiles/'+id+'/change',{employer:f.taxInput.employer,effectiveOn:'2026-02-01',expectedVersion:1,definition:{...f.definition,additionalIncomeTaxPerPay},reason:'Synthetic correction'})));assert.deepEqual(changed.map(r=>r.response.status).sort(),[200,409]);assert.equal((await f.pg.query('SELECT * FROM public.payroll_tax_profile_revisions')).rows.length,2);
},true);
check('tax settings native header writes wait for the payroll worker source fence without changing unapproved history',async f=>{
 const r=await f.createTax();assert.equal(r.response.status,201);const owner=await f.pg.runtime!.connect(),writer=await f.pg.runtime!.connect();let update:Promise<unknown>|undefined;
 try{for(const c of [owner,writer]){await c.query('BEGIN');await c.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);}await writer.query("SET LOCAL lock_timeout='2s'");const pid=(await owner.query<{pid:number}>('SELECT pg_backend_pid() pid')).rows[0].pid;await owner.query('SELECT public.lock_hourly_worker($1)',[f.actors.staff.person]);update=writer.query('UPDATE public.payroll_tax_profiles SET version=version+1 WHERE id=$1',[r.body.data.id]);let blocked=false;const until=Date.now()+1000;while(Date.now()<until&&!blocked){blocked=(await f.pg.query<{blocked:boolean}>('SELECT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE $1::integer=ANY(pg_blocking_pids(a.pid))) blocked',[pid])).rows[0].blocked;if(!blocked)await delay(5);}assert.equal(blocked,true);assert.equal((await f.pg.query<{version:number}>('SELECT version FROM public.payroll_tax_profiles WHERE id=$1',[r.body.data.id])).rows[0].version,1);await owner.query('COMMIT');await update;await writer.query('ROLLBACK');assert.equal((await f.pg.query<{version:number}>('SELECT version FROM public.payroll_tax_profiles WHERE id=$1',[r.body.data.id])).rows[0].version,1);
 }finally{await owner.query('ROLLBACK');await update?.catch(()=>{});await writer.query('ROLLBACK');owner.release();writer.release();}
},true);
test('tax settings actual168to169 migration preserves existing financial work and approval history without guessing employee declarations',async()=>{
 const f=await fixture(168);try{const before=[];for(const t of ['people','roles','role_permissions','role_assignments','financial_payees','financial_payee_revisions','work_engagements','approval_requests','audit_events'])before.push((await f.pg.query('SELECT * FROM public.'+t+' ORDER BY 1,2')).rows);await f.pg.exec(await readFile(new URL('../db/migrations/169_payroll_tax_profiles.sql',import.meta.url),'utf8'));let i=0;for(const t of ['people','roles','role_permissions','role_assignments','financial_payees','financial_payee_revisions','work_engagements','approval_requests','audit_events'])assert.deepEqual((await f.pg.query('SELECT * FROM public.'+t+' ORDER BY 1,2')).rows,before[i++]);assert.equal((await f.pg.query('SELECT * FROM public.payroll_tax_profiles')).rows.length,0);await upgradeToCurrent(f.pg);assert.equal((await f.createTax()).response.status,201);}finally{await f.pg.close();}
});
